package httpx
import("net/http";"strings")
type CORS struct{AllowedOrigins []string}
func(c CORS)Middleware(next http.Handler)http.Handler{allowed:=make(map[string]struct{},len(c.AllowedOrigins));for _,origin:=range c.AllowedOrigins{origin=strings.TrimSpace(origin);if origin!=""&&origin!="*"{allowed[origin]=struct{}{}}};return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){if w==nil{return};if r==nil{w.WriteHeader(http.StatusBadRequest);return};origin:=strings.TrimSpace(r.Header.Get("Origin"));if origin!=""{if _,ok:=allowed[origin];ok{w.Header().Set("Access-Control-Allow-Origin",origin);w.Header().Add("Vary","Origin");w.Header().Set("Access-Control-Allow-Credentials","true");w.Header().Set("Access-Control-Allow-Headers","Authorization, Content-Type, X-Request-ID");w.Header().Set("Access-Control-Allow-Methods","GET, POST, PUT, PATCH, DELETE, OPTIONS")}else if r.Method==http.MethodOptions{w.WriteHeader(http.StatusForbidden);return}};if r.Method==http.MethodOptions{w.WriteHeader(http.StatusNoContent);return};if next==nil{w.WriteHeader(http.StatusNotFound);return};next.ServeHTTP(w,r)})}
